# Source of truth for the knowledge base: edit here, run `python3 ledger/kb/build-kb.py`, commit both files.
import json
V = "2026-10-19.3"
VER = "2026-10-19"
LII = "https://www.law.cornell.edu/uscode/text/15/"
E = "https://www.ecfr.gov/current/title-12/chapter-X/"
R = []
def r(id, section, title, rule, cite, url, **kw):
    R.append(dict(id=id, section=section, title=title, rule=rule, cite=cite, url=url, verifiedAt=VER, **kw))

# ---------- PERSONAL: FCRA ----------
r("fcra-605", "personal", "Reporting time limits (obsolescence)", "Most negative items (collections, charge-offs, late payments) may be reported for 7 years. The clock runs from 180 days after the delinquency that led to the collection or charge-off began (the DOFD). Chapter 7 bankruptcies can be reported for 10 years. Paying a debt does not restart the clock.", "FCRA § 605(a), (c); 15 U.S.C. § 1681c", LII + "1681c")
r("fcra-609", "personal", "File disclosure", "Consumers can get everything in their file from each nationwide bureau. Free reports are available weekly at AnnualCreditReport.com.", "FCRA § 609, § 612; 15 U.S.C. §§ 1681g, 1681j", LII + "1681g", extraUrls=["https://www.annualcreditreport.com/"])
r("fcra-611", "personal", "Bureau reinvestigation: 30 days (up to 45)", "After a dispute, the bureau must finish a reasonable reinvestigation within 30 days of receipt, extendable to 45 days if the consumer sends more information during the 30 days, or if the dispute follows a free annual report. It must forward the dispute to the furnisher within 5 business days and send results within 5 business days of finishing.", "FCRA § 611(a)(1), (a)(2), (a)(6); 15 U.S.C. § 1681i", LII + "1681i")
r("fcra-611-frivolous", "personal", "Frivolous or irrelevant disputes", "A bureau may refuse a dispute it reasonably finds frivolous or irrelevant, including one with no new information or one that does not give enough detail. It must tell the consumer within 5 business days. Repeat, template or mass disputes risk this.", "FCRA § 611(a)(3); 15 U.S.C. § 1681i(a)(3)", LII + "1681i")
r("fcra-611-mov", "personal", "Method of verification", "After a reinvestigation the consumer may ask for a description of how it was done, including the furnisher's name, address and phone number if reasonably available. The bureau must answer within 15 days.", "FCRA § 611(a)(6)(B)(iii), (a)(7)", LII + "1681i")
r("fcra-611-reinsert", "personal", "Reinsertion of deleted items", "A deleted item can only come back if the furnisher certifies it is complete and accurate. The bureau must notify the consumer in writing within 5 business days.", "FCRA § 611(a)(5)(B)", LII + "1681i")
r("fcra-623", "personal", "Furnisher accuracy duties", "Furnishers must not report information they know is inaccurate, must correct and update it, must report an account as disputed when the consumer disputes it with them, and must report the date of delinquency for accounts placed in collection or charged off.", "FCRA § 623(a)(1)-(3), (a)(5); 15 U.S.C. § 1681s-2", LII + "1681s-2")
r("regv-1022-43", "personal", "Direct disputes to the furnisher", "Consumers can dispute directly with the furnisher about account terms, liability, payment history and similar items. The dispute must identify the account, say what is wrong and why, and include supporting documents. The furnisher has the same time limits as a bureau (generally 30 days). Furnishers may treat disputes as frivolous, for example when they come from a credit repair organization's form letter.", "Reg. V, 12 C.F.R. § 1022.43", E + "part-1022/subpart-E/section-1022.43")
r("fdcpa-809", "personal", "Debt validation", "A debt collector must send a validation notice. If the consumer disputes in writing within the 30-day validation period, the collector must stop collecting until it mails verification. Under Reg F the validation period ends 30 days after the consumer receives the notice (assumed 5 business days after it is sent).", "FDCPA § 809, 15 U.S.C. § 1692g; Reg. F, 12 C.F.R. § 1006.34", LII + "1692g", extraUrls=[E + "part-1006/subpart-B/section-1006.34"])
r("fcba", "personal", "Billing errors on credit cards", "For open-end credit (credit cards), a billing error must be disputed in writing to the card issuer within 60 days of the statement. The issuer must acknowledge within 30 days and resolve within two billing cycles (no more than 90 days), and it may not report the disputed amount as delinquent while it investigates.", "FCBA, 15 U.S.C. § 1666; Reg. Z, 12 C.F.R. § 1026.13", LII + "1666", extraUrls=[E + "part-1026/subpart-B/section-1026.13"])
r("ecoa-adverse", "personal", "Adverse action notices", "A lender that denies credit must send a notice within 30 days of a completed application that gives the specific principal reasons or says how to request them. If a credit report was used, FCRA § 615 also requires the bureau's name and the right to a free report within 60 days.", "ECOA, 15 U.S.C. § 1691(d); Reg. B, 12 C.F.R. § 1002.9; FCRA § 615", E + "part-1002/section-1002.9")


# ---------- PERSONAL: identifiers, inquiries, files that aren't yours (v2) ----------
r("pii-611", "personal", "Personal information disputes (names, addresses, employers, DOB, SSN variations)", "Wrong or outdated identifiers can be disputed with each bureau like any other inaccuracy. Bureaus must follow reasonable procedures for maximum possible accuracy. A bureau may keep a current address it can verify, and old addresses or name variants that were really used are not inaccurate. Staff see DOB and SSN variations masked. Identity theft disputes are out of scope; refer clients to IdentityTheft.gov.", "FCRA §§ 607(b), 611; 15 U.S.C. §§ 1681e(b), 1681i", LII + "1681e")
r("fcra-604-inquiry", "personal", "Inquiries need a permissible purpose", "A report may be pulled only for a permissible purpose (e.g. a credit application the consumer made, account review, written authorization). A hard inquiry the consumer does not recognize can be disputed with the bureau. Identity theft disputes are out of scope; refer clients to IdentityTheft.gov. Inquiries the consumer did authorize are accurate and are not disputed.", "FCRA §§ 604, 611; 15 U.S.C. §§ 1681b, 1681i", LII + "1681b")
r("inq-2yr", "personal", "How long hard inquiries show", "Bureaus generally keep hard inquiries on the report for about 2 years (FICO scores count them for 12 months). FCRA § 609(a)(3) requires disclosure of inquiries from the past year (2 years for employment). A hard inquiry still showing after 2 years can be raised with the bureau as outdated under its own retention policy; it is not a statutory violation.", "Experian consumer education; FCRA § 609(a)(3)", "https://www.experian.com/blogs/ask-experian/how-long-do-hard-inquiries-stay-on-credit-report/", extraUrls=[LII + "1681g"])
r("consumer-asserted", "personal", "Items the consumer says are inaccurate or unverifiable", "A consumer may dispute any item they believe is inaccurate or incomplete. The dispute must say specifically what is wrong and why (with documents if available). If the bureau cannot verify an item within the reinvestigation period it must delete or modify it. Accurate, timely, verified negative items are not disputed.", "FCRA § 611(a)(1), (a)(5)(A); Reg. V § 1022.43(d)", LII + "1681i")

# ---------- CROA / compliance ----------
r("croa-advance-fee", "compliance", "No fees before services are fully performed", "A credit repair organization may not charge or receive any money for a service before that service is fully performed. The Telemarketing Sales Rule adds that, when sold by phone, payment can only be requested after the promised results are shown in a consumer report issued more than 6 months after the results were achieved.", "CROA § 404(b), 15 U.S.C. § 1679b(b); TSR, 16 C.F.R. § 310.4(a)(2)", LII + "1679b", extraUrls=["https://www.ecfr.gov/current/title-16/chapter-I/subchapter-C/part-310/section-310.4"])
r("croa-misrep", "compliance", "No untrue or misleading statements", "No one may advise a consumer to make untrue or misleading statements to a bureau or creditor, to alter identity to hide accurate information (e.g. CPNs or EINs used as an SSN), or misrepresent the services. Never promise results, deletions or score increases.", "CROA § 404(a), 15 U.S.C. § 1679b(a)", LII + "1679b")
r("croa-disclosure", "compliance", "Required written disclosure", "Before any contract is signed, the consumer must receive the 'Consumer Credit File Rights Under State and Federal Law' statement, in the statutory wording, as a separate document. The organization must keep a signed copy for 2 years.", "CROA § 405, 15 U.S.C. § 1679c", LII + "1679c")
r("croa-contract", "compliance", "Written contract", "The contract must be in writing, signed by the consumer, and list the terms and conditions of payment including the total amount, a full description of the services, the estimated time to perform them, the organization's name and principal business address, and a conspicuous cancellation notice.", "CROA § 406, 15 U.S.C. § 1679d", LII + "1679d")
r("croa-cancel", "compliance", "3-business-day cancellation", "The consumer can cancel without penalty or obligation before midnight of the 3rd business day after signing. The organization must give a separate cancellation form. A contract that does not comply with CROA is void.", "CROA §§ 407-408, 15 U.S.C. §§ 1679e-1679f", LII + "1679e")
r("croa-waiver", "compliance", "No waivers", "Any waiver of CROA rights is void and cannot be enforced.", "CROA § 408, 15 U.S.C. § 1679f", LII + "1679f")
r("ftc-affiliate", "compliance", "Affiliate and referral disclosures", "If we earn money when someone signs up through our link, we must say so clearly and conspicuously, near the link, every time we recommend it.", "FTC Endorsement Guides, 16 C.F.R. Part 255", "https://www.ecfr.gov/current/title-16/chapter-I/subchapter-B/part-255", extraUrls=["https://www.ftc.gov/business-guidance/resources/ftcs-endorsement-guides-what-people-are-asking"])
r("nj-credit-repair", "compliance", "New Jersey", "New Jersey has no stand-alone credit services organization statute. The NJ Division of Consumer Affairs points consumers to the federal CROA protections: no payment before services are completed, written rights disclosure, written contract, and 3 days to cancel. Separately, N.J.S.A. 17:16G (Debt Adjustment and Credit Counseling) licenses debt adjusters and caps their fees. Offering to negotiate or settle debts for NJ consumers can fall under it, so have a NJ attorney confirm the business model. The NJ Consumer Fraud Act (N.J.S.A. 56:8) also applies to advertising.", "NJ Div. of Consumer Affairs brief (rev. 06/13/23); N.J.S.A. 17:16G; N.J.S.A. 56:8", "https://www.njconsumeraffairs.gov/News/Consumer%20Briefs/credit-reports-and-credit-repair.pdf", needsLawyer=True)
r("tcpa-sms", "compliance", "Texts and calls", "Texting a client requires their prior express consent, and marketing texts require prior express written consent. Keep the consent record and honor STOP.", "TCPA, 47 U.S.C. § 227; 47 C.F.R. § 64.1200", "https://www.ecfr.gov/current/title-47/chapter-I/subchapter-B/part-64/subpart-L/section-64.1200")

# ---------- Metro 2 ----------
CDIA = "https://www.cdiaonline.org/resources/furnishers-of-data-overview/metro2-information/"
r("m2-overview", "metro2", "Metro 2 format", "Metro 2 is the standard format furnishers use to report to the bureaus. The Credit Reporting Resource Guide (CRRG) from the CDIA defines each field. The fields must be consistent with one another: Account Status, Payment Rating, the 24-month Payment History Profile, Current Balance, Amount Past Due, DOFD and the Compliance Condition Code.", "CDIA Credit Reporting Resource Guide", CDIA)
r("m2-dofd", "metro2", "Date of First Delinquency (DOFD)", "The DOFD is the date the account first became delinquent and was never brought current afterward. It controls the 7-year reporting period. It must not change when the debt is sold, transferred or paid. A DOFD that moves later is called re-aging.", "CRRG Base Segment field 25; FCRA § 623(a)(5)", CDIA, extraUrls=[LII + "1681s-2"])
r("m2-status", "metro2", "Account Status codes", "Examples: 11 current, 13 paid/closed zero balance, 71-84 increasingly past due, 93 collection, 97 charge-off, 62/64 paid collection/charge-off, 05 transferred. A paid or transferred status must show a zero balance and no amount past due.", "CRRG Base Segment field 17A", CDIA)
r("m2-ccc", "metro2", "Compliance Condition Codes", "XB = disputed, investigation under way; XC = investigation completed, consumer disagrees; XH = previously in dispute, investigation completed; XR = removes the most recent code. After an investigation, XB should be replaced.", "CRRG Base Segment field 20; FCRA § 623(a)(3)", CDIA)
r("m2-history", "metro2", "Payment History Profile", "This is 24 months of history, newest month first. 0 = current, 1-6 = 30 to 180+ days late, G = collection, L = charge-off, B = no history before this month, D = no data for the month. The latest month must match the Account Status.", "CRRG Base Segment field 18", CDIA)

# ---------- Score building ----------
r("score-factors", "personal", "What moves FICO scores", "Payment history (about 35%), amounts owed and utilization (30%), length of history (15%), new credit (10%), credit mix (10%). Keep card utilization low (under 30%, lower is better), pay on time, avoid closing old cards, and space out applications.", "myFICO: What's in your credit score", "https://www.myfico.com/credit-education/whats-in-your-credit-score", extraUrls=["https://www.consumerfinance.gov/ask-cfpb/how-do-i-get-and-keep-a-good-credit-score-en-318/"])
r("score-au", "personal", "Authorized users", "Being added as an authorized user on a well-managed card can help a thin file. The primary holder's late payments can hurt it, and an AU can ask to be removed. Never buy 'tradeline' seats to misrepresent history to a lender.", "CFPB consumer guidance", "https://www.consumerfinance.gov/ask-cfpb/how-do-i-get-and-keep-a-good-credit-score-en-318/")
r("score-goodwill", "personal", "Goodwill and pay-for-update requests", "Accurate negatives cannot be disputed away. A consumer can ask a creditor, as a courtesy, to update a paid late payment ('goodwill letter'). Creditors don't have to agree, and the letter must not claim the item is inaccurate.", "FCRA § 623(a)(1) (accuracy); CROA § 404(a)", LII + "1681s-2")

# ---------- BUSINESS ----------
r("biz-fcra-scope", "business", "Business credit reports are mostly NOT covered by the FCRA", "The FCRA covers reports about consumers (individuals). Commercial credit reports on a business (D&B, Experian Business, Equifax Business) are generally outside it. So there is no federal 30-day reinvestigation duty: disputes go through each bureau's own process and to the furnisher. A personal report pulled for a personal guarantee IS covered by the FCRA.", "FCRA § 603(c)-(d), 15 U.S.C. § 1681a", LII + "1681a")
r("biz-dnb", "business", "Dun & Bradstreet disputes and updates", "Owners, directors or officers can verify through the free D-U-N-S Profile Manager to update company information and dispute payment experiences. D&B reviews requests and may not accept them. A D-U-N-S Number is free, and paying to expedite it is optional.", "D&B D-U-N-S Profile Manager", "https://www.dnb.com/en-us/smb/duns/duns-manager.html", extraUrls=["https://www.dnb.com/duns/get-a-duns.html"])
r("biz-experian", "business", "Experian Business disputes", "Use 'Submit Data Dispute' on the Experian business report, or email the marked-up report to BusinessDisputes@Experian.com. Investigations generally finish within 30 days. Officers can update profile facts at businesscreditfacts.com.", "Experian Small Business", "https://www.experian.com/small-business/business-credit-information")
r("biz-equifax", "business", "Equifax Business", "Business support portal; 1-888-407-0359. Equifax Commercial Solutions, PO Box 740249, Atlanta, GA 30374-0249.", "Equifax Business support", "https://www.equifax.com/business/support/")
r("biz-sbfe", "business", "SBFE", "The Small Business Financial Exchange is a lender-owned data exchange, not a credit bureau. Member lenders report payment data that partner bureaus use in some products. Dispute with the bureau that issued the report and with the lender.", "SBFE FAQ", "https://www.sbfe.org/small-business-faqs")
r("biz-reg-b", "business", "ECOA / Reg B for business credit", "ECOA applies to business credit too: no discrimination on a prohibited basis, and businesses get adverse action notices (with simplified rules for businesses with gross revenues of $1 million or less).", "Reg. B, 12 C.F.R. § 1002.9(a)(3)", E + "part-1002/section-1002.9")
r("biz-1071", "business", "CFPB Section 1071 (small business lending data)", "On May 1, 2026, the CFPB issued a revised 1071 rule (effective June 30, 2026). Covered lenders, those with at least 1,000 small-business originations in each of 2026 and 2027, must start collecting data on January 1, 2028, and 2028 is a grace year. 'Small business' now means $1 million or less in gross annual revenue. This is a lender data-collection rule. It doesn't change how business credit is scored or disputed.", "Reg. B subpart B (12 C.F.R. 1002.101 et seq.), CFPB final rule May 1, 2026", "https://www.consumerfinance.gov/rules-policy/final-rules/small-business-lending-under-the-equal-credit-opportunity-act-regulation-b-2026/", extraUrls=["https://www.consumerfinance.gov/1071-rule/"])
r("biz-building", "business", "Building business credit", "Foundation: a registered entity in good standing, an EIN, a business bank account, a consistent legal name, address and phone everywhere, a D-U-N-S Number, and an accurate NAICS code. Then open net-30 vendor accounts that report to business bureaus, pay early, and add reporting cards or credit-builder accounts. Keep personal and business spending separate.", "SBA guidance; Nav net-30 list", "https://www.sba.gov/business-guide/manage-your-business/manage-your-finances", extraUrls=["https://www.nav.com/business-credit/net-30-accounts/"])
r("biz-pg", "business", "Personal guarantees", "Most small-business credit needs a personal guarantee. The lender may pull the owner's personal report (an FCRA-covered hard inquiry). Some business cards report to personal reports, and a default on a guaranteed debt can show up on the owner's personal credit.", "CFPB small business resources", "https://www.consumerfinance.gov/consumer-tools/small-business/")

r("biz-dispute-letters", "business", "Business bureau correction letters", "Business files are corrected through each bureau's own process (D&B D-U-N-S Manager / iUpdate, Experian business dispute, Equifax business support), not FCRA § 611. Dispute specific facts: wrong name, address, phone, formation date, SIC/NAICS, tradelines that are not the business's, stale or closed accounts shown open, paid accounts with balances, duplicates, and liens or judgments satisfied but shown open (send the release or satisfaction).", "Bureau dispute processes; FCRA § 603(d) (scope)", "https://www.dnb.com/en-us/smb/duns/duns-manager.html", extraUrls=["https://www.experian.com/small-business/business-credit-information", "https://www.equifax.com/business/support/"])
r("biz-util-intelliscore", "business", "Utilization affects Experian Intelliscore", "Experian lists credit utilization and trends over time, balances outstanding, number of trade experiences and payment habits among the credit factors in Intelliscore Plus, alongside public records and business demographics. Experian does not publish a utilization threshold. Keeping balances low relative to limits may help.", "Experian: Understanding your business credit score", "https://www.experian.com/small-business/business-credit-score")
r("biz-paydex-timing", "business", "PAYDEX is about payment timing, not utilization", "D&B's PAYDEX is a dollar-weighted index of reported payment experiences: 80 means paid on terms, 90 about 20 days early, 100 about 30 days early. Balances and utilization are not part of PAYDEX, so paying vendors before the due date matters most. Only reported experiences count, so confirm vendors report to D&B.", "D&B PAYDEX fact sheet; D&B Analytics quick reference", "https://www.dnb.com/en-us/smb/resources/credit-scores/what-is-paydex-score.html", extraUrls=["https://www.dnb.com/content/dam/web/data-and-ai/cross/content/paydex-score-factsheet/DnB_Paydex_Score_Factsheet.pdf"])
r("util-30", "business", "Keeping utilization low (personal and business)", "Scoring models look at how close balances are to limits. The CFPB says experts advise using no more than 30% of total credit limits, and lower is better; paying in full avoids interest. Lawful ways to lower utilization: pay before the statement closing date, pay down balances, ask for a limit increase, and spread spending across accounts. Results vary by model; no score change is guaranteed.", "CFPB: How do I get and keep a good credit score?", "https://www.consumerfinance.gov/ask-cfpb/how-do-i-get-and-keep-a-good-credit-score-en-318/", extraUrls=["https://www.fdic.gov/resources/consumers/consumer-assistance-topics/credit-reports.html"])
r("util-guarantee", "business", "Owner-guaranteed accounts and personal utilization", "Many small-business cards and lines are personally guaranteed, and some report to the owner's personal credit file. When they do, their balances can count toward the owner's personal utilization. Check each issuer's reporting policy.", "CFPB small business resources; issuer reporting policies", "https://www.consumerfinance.gov/consumer-tools/small-business/")

# ---------- BUY A CORPORATION ----------
r("corp-structure", "corp", "Stock purchase vs. asset purchase", "In a stock (or membership-interest) purchase you buy the entity itself, including all its liabilities, known and unknown. In an asset purchase you buy selected assets, and liabilities generally stay with the seller. The choice affects taxes, contracts, licenses and liability. Use an attorney and a CPA.", "SBA: Buy an existing business", "https://www.sba.gov/business-guide/plan-your-business/buy-existing-business-or-franchise", needsLawyer=True)
r("corp-diligence", "corp", "Due diligence checklist", "Check the Secretary of State good standing and filing history, UCC lien searches, judgments and court records (state courts and PACER), federal and state tax status (IRS Form 8821 transcript, state tax clearance), the registered agent, the officers and members of record, contracts, licenses, bank statements and tax returns showing real operations.", "SBA; IRS Form 8821; PACER", "https://www.irs.gov/forms-pubs/about-form-8821", extraUrls=["https://pacer.uscourts.gov/", "https://www.sba.gov/business-guide/plan-your-business/buy-existing-business-or-franchise"])
r("corp-changes", "corp", "After closing", "File officer, member and registered-agent changes with the state. Update the IRS responsible party (Form 8822-B within 60 days). Update D&B and bank signers. Tell lenders and vendors about the ownership change.", "IRS Form 8822-B", "https://www.irs.gov/forms-pubs/about-form-8822-b")
r("corp-boi", "corp", "Beneficial ownership (BOI) reporting status", "FinCEN's final rule effective August 14, 2026 permanently exempts U.S.-created companies and U.S. persons from BOI reporting under the Corporate Transparency Act. Only certain foreign companies registered in the U.S. still report, and only for foreign beneficial owners. A purchase of a domestic company needs no FinCEN BOI filing. Check state-level ownership filings.", "31 C.F.R. § 1010.380; FinCEN final rule, 91 FR 52508 (Aug. 14, 2026)", "https://www.federalregister.gov/documents/2026/08/14/2026-16576/beneficial-ownership-information-reporting-requirement-revision", extraUrls=["https://www.fincen.gov/boi/beneficial-ownership-information-frequently-asked-questions"])
r("corp-fraud-warning", "corp", "Misrepresenting an aged or shelf company is fraud risk", "A bought company's formation date isn't your operating history. Telling a lender the business has operated for X years, or presenting the prior owner's credit history or revenue as yours, can be bank fraud or false statements on a loan application (18 U.S.C. §§ 1014, 1344). Lenders and bureaus look at ownership changes, the D-U-N-S and SOS officer history, bank statements and tax returns. An aged shell with no tradelines, revenue or filings adds little. No company is 'instantly fundable'. Always disclose the purchase date and the true ownership history.", "18 U.S.C. § 1014; 18 U.S.C. § 1344", "https://www.law.cornell.edu/uscode/text/18/1014", extraUrls=["https://www.law.cornell.edu/uscode/text/18/1344"], needsLawyer=True)
r("corp-credit-link", "corp", "How a purchase does and doesn't tie to business credit", "A real operating business keeps its D-U-N-S file, vendor tradelines and payment history after a stock purchase, but lenders reunderwrite on the new owners, their personal guarantees and their credit. Many vendor and bank accounts must be reopened or re-approved after a change of control. Formation age alone doesn't create tradelines.", "D&B update guidance (ownership change)", "https://www.dnb.com/en-us/smb/duns/duns-manager.html")

kb = {"version": V, "updated": VER, "note": "Plain-English summaries for staff and the Ledger Assistant. Not legal advice. Each rule cites its official source; re-verify before relying on it.", "rules": R}
import os
here = os.path.dirname(os.path.abspath(__file__))
json.dump(kb, open(os.path.join(here, "ledger-kb.json"), "w"), indent=1, ensure_ascii=False)
js = "/* Generated from ledger/kb/build-kb.py — do not edit by hand. */\n(function (root) { 'use strict'; const KB = " + json.dumps(kb, ensure_ascii=False) + ";\n KB.byId = id => KB.rules.find(r => r.id === id);\n KB.section = s => KB.rules.filter(r => r.section === s);\n root.KB = KB; if (typeof module !== 'undefined' && module.exports) module.exports = KB; })(typeof window !== 'undefined' ? window : globalThis);\n"
open(os.path.join(here, "..", "js", "kb.js"), "w").write(js)
print(len(R), "rules")
